import { deriveKeys, rand } from '@nullifex/crypto'

const nullifex = new NullifexClient({
  connection, programId,
  indexerUrl: 'https://indexer.example', relayerUrl: 'https://relayer.example',
  circuit: { wasm: '/circuits/transaction.wasm', zkey: '/circuits/transaction.zkey' }
})
nullifex.unlock(deriveKeys(rand(32)))   // keep the 32-byte root safe: it is the vault
await nullifex.sync()                      // download notes, find yours by trial decryption
console.log(nullifex.rootStatus)           // 'ok': checked against the program's own root on-chain

// tokens are named by mint (a token's own symbol is never trusted)
const SOL_MINT = 'So11111111111111111111111111111111111111112'
const USDC_MINT = 'EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v'
for (const m of [SOL_MINT, USDC_MINT]) await nullifex.resolveAsset(m)   // reads each token's Nullifex config from chain`],["Shield",`// the only step the wallet signs
const tx = await nullifex.buildDeposit(wallet.publicKey, SOL_MINT, 1_000_000_000n)
await wallet.sendTransaction(tx, connection)`],["Send",`// relayed, no wallet signature; fee in private SOL when possible
const r = await nullifex.transfer('veil2…', USDC_MINT, 25_000_000n)
console.log(r.hidden)   // true: the transaction names no USDC account`],["Trade",`const q = await nullifex.relayer.quote(SOL_MINT, USDC_MINT, 500_000_000n)
const minOut = BigInt(q.amountOut) * 995n / 1000n   // 0.5% slippage
// minOut comes from the relayer's quote: compare it with a price you trust before using it
await nullifex.swap(SOL_MINT, USDC_MINT, 500_000_000n, minOut, undefined, { maxFee: 3_000_000n })`],...I?[["Flow DCA",`// sell 10 SOL for USDC: 7 orders, one a day, the first now
