const mine = await nullifex.flows()          // your orders, their fills and progress
await nullifex.flowCancel(order)             // what isn't sold comes back privately`]]:[],["Earn",`await nullifex.lend(USDC_MINT, 100_000_000n)        // private jlUSDC note
await nullifex.redeem(JLUSDC_MINT, 95_000_000n)     // back to private USDC`],["Withdraw","await nullifex.withdraw(new PublicKey('…'), SOL_MINT, 250_000_000n)   // native SOL to any wallet"]]})]})},{id:"api",group:"Build",title:"Relayer & indexer API",keys:"api endpoint relayer indexer http rest",body:(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)("h2",{children:"Relayer & indexer API"}),(0,s.jsxs)("p",{children:["Both are plain HTTP and keep no logs of who asked what. Anyone can run their own. Which addresses the app may connect to, checked live in your browser: ",(0,s.jsx)("a",{href:"/api",children:"API"}),"."]}),(0,s.jsx)("div",{className:"tbl-wrap",children:(0,s.jsxs)("table",{className:"tbl",children:[(0,s.jsx)("thead",{children:(0,s.jsxs)("tr",{children:[(0,s.jsx)("th",{children:"Endpoint"}),(0,s.jsx)("th",{children:"What it does"})]})}),(0,s.jsxs)("tbody",{children:[(0,s.jsxs)("tr",{children:[(0,s.jsx)("td",{className:"mono",children:"GET /v1/info"}),(0,s.jsx)("td",{children:"Relayer key, allowlisted swap and lending programs, protocol fee rates"})]}),(0,s.jsxs)("tr",{children:[(0,s.jsx)("td",{className:"mono",children:"GET /v1/fee?mint&inputs"}),(0,s.jsx)("td",{children:"Relayer fee for a token and number of notes spent, and the account it's paid to"})]}),(0,s.jsxs)("tr",{children:[(0,s.jsx)("td",{className:"mono",children:"POST /v1/relay"}),(0,s.jsx)("td",{children:"Submit a proof (transfer, withdrawal, trade, lend); the relayer pays the network fee"})]}),(0,s.jsxs)("tr",{children:[(0,s.jsx)("td",{className:"mono",children:"POST /v1/sponsor"}),(0,s.jsx)("td",{children:"Gasless shield: co-sign a deposit as fee payer after a strict check"})]}),(0,s.jsxs)("tr",{children:[(0,s.jsx)("td",{className:"mono",children:"GET /v1/quote"}),(0,s.jsx)("td",{children:"Swap or lending quote, after the Nullifex fee"})]}),(0,s.jsxs)("tr",{children:[(0,s.jsx)("td",{className:"mono",children:"GET /v1/positions"}),(0,s.jsx)("td",{children:"Lending markets, rates and share prices"})]